import { Command } from 'commander';
import { git } from '../utils/git.js';
import { scanForSecrets } from '../utils/security.js';

export function registerScan(program: Command) {
  program
    .command('scan')
    .description('Secret scanner for staged files')
    .action(async () => {
      const files = await git().diff(['--cached', '--name-only']);
      const list = files.split('\n').filter(Boolean);
      const findings = scanForSecrets(list);
      if (findings.length === 0) {
        console.log('No secrets detected.');
        return;
      }
      console.log('⚠️  Potential secrets found:');
      findings.forEach(f => console.log(`- ${f.file}: ${f.match}`));
      process.exitCode = 1;
    });
}
